import { createHash } from 'node:crypto';
import { join } from 'node:path';
import type { Plugin } from 'vite';
import {
  DEFAULT_SITE_URL,
  catalogToJson,
  llmsTxt,
  loadRegistry,
  resourceExportToJson,
} from '@ecosystem-skills/catalog';

/**
 * Generates catalog.json from registry/*.json as part of the Vite build, so every production build of the
 * site contains it, whichever command runs `vite build` (the root script, the package script, or a host's
 * framework default). The catalog is emitted straight into the build output, not into public/, so no
 * generated file has to exist before the build and a stale copy can never be published.
 *
 * It reuses the registry loader of @ecosystem-skills/catalog (the same strict validation as
 * `pnpm catalog:validate`) and fails the build with the validation errors if the registry is invalid:
 * a site without a catalog must never be deployed.
 *
 * ES26 adds, all derived from that same validated public catalog (never from private roots or local paths):
 *  - llms.txt and resources.v1.json, the AI-readable references (see packages/catalog/src/public.ts);
 *  - manifest.webmanifest and sw.js, the PWA files (see docs/website.md, "Installable app and offline use").
 */

/** Files the plugin serves in dev and emits in a build, by public path. */
export function publicFiles(
  registryRoot: string,
  siteUrl: string,
  base: string,
): Record<string, string> {
  let catalog;
  try {
    catalog = loadRegistry(registryRoot).catalog;
  } catch (e) {
    throw new Error(`Catalog generation failed: ${e instanceof Error ? e.message : String(e)}`, {
      cause: e,
    });
  }
  return {
    'catalog.json': catalogToJson(catalog),
    'llms.txt': llmsTxt(catalog, siteUrl),
    'resources.v1.json': resourceExportToJson(catalog),
    'manifest.webmanifest': webManifest(base),
  };
}

export function webManifest(base: string): string {
  return (
    JSON.stringify(
      {
        name: 'Ecosystem Skills',
        short_name: 'Skills',
        description:
          'A read-only registry of AI-agent skills and catalogued resources: provenance, review status and agent evidence.',
        id: base,
        start_url: base,
        scope: base,
        display: 'standalone',
        background_color: '#fafafa',
        theme_color: '#4f46e5',
        icons: [
          { src: `${base}icons/icon-192.png`, sizes: '192x192', type: 'image/png', purpose: 'any' },
          { src: `${base}icons/icon-512.png`, sizes: '512x512', type: 'image/png', purpose: 'any' },
          {
            src: `${base}icons/icon-maskable-512.png`,
            sizes: '512x512',
            type: 'image/png',
            purpose: 'maskable',
          },
          { src: `${base}icons/icon.svg`, sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
        ],
      },
      null,
      2,
    ) + '\n'
  );
}

/**
 * The service worker. Deliberately small:
 *  - the app shell (index.html and the hashed build files) is cached at install, so the site opens offline;
 *  - page navigations go to the network first and fall back to the cached shell (every route is the same SPA);
 *  - catalog.json, llms.txt and resources.v1.json go to the network first; only when the network fails is the
 *    cached copy returned, marked with the offline header so the app says it may be stale and not authoritative;
 *  - hashed /assets/ files are cache-first (their names change with their content);
 *  - other origins and non-GET requests are never touched, and nothing private exists to cache.
 * The cache name includes a hash of the precache list, so a new build replaces the old cache on activation.
 */
export function serviceWorker(base: string, precache: string[]): string {
  const version = createHash('sha256').update(precache.join('\n')).digest('hex').slice(0, 12);
  return `/* Ecosystem Skills service worker (generated by catalog-plugin.ts). */
const CACHE = 'ecosystem-skills-${version}';
const BASE = ${JSON.stringify(base)};
const PRECACHE = ${JSON.stringify(precache.map((p) => base + p))};
const DATA = ['catalog.json', 'llms.txt', 'resources.v1.json'].map((p) => BASE + p);
const OFFLINE_HEADER = 'X-Ecosystem-Skills-Offline';
// Same-origin static files only: a module script's Origin header must not defeat the match (servers send Vary: Origin).
const MATCH = { ignoreVary: true };

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('ecosystem-skills-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

async function markedOffline(response) {
  const headers = new Headers(response.headers);
  headers.set(OFFLINE_HEADER, '1');
  return new Response(await response.blob(), { status: response.status, statusText: response.statusText, headers });
}
async function networkFirst(request, fallback) {
  const cache = await caches.open(CACHE);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch (error) {
    const cached =
      (await cache.match(request, MATCH)) || (fallback && (await cache.match(fallback, MATCH)));
    if (!cached) throw error;
    return fallback ? cached : markedOffline(cached);
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin || !url.pathname.startsWith(BASE)) return;
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, BASE + 'index.html'));
  } else if (DATA.includes(url.pathname)) {
    event.respondWith(networkFirst(request));
  } else if (url.pathname.startsWith(BASE + 'assets/')) {
    event.respondWith(caches.match(request, MATCH).then((hit) => hit || fetch(request).then((response) => {
      if (response.ok) caches.open(CACHE).then((c) => c.put(request, response.clone()));
      return response;
    })));
  }
});
`;
}

export function catalogPlugin({ registryRoot }: { registryRoot: string }): Plugin {
  const siteUrl = (base: string) =>
    `${(process.env.SITE_URL ?? DEFAULT_SITE_URL).replace(/\/+$/, '')}${base.replace(/\/+$/, '')}`;
  let serving = false;
  let base = '/';
  return {
    name: 'ecosystem-skills-catalog',
    configResolved(config) {
      serving = config.command === 'serve';
      base = config.base;
    },
    buildStart() {
      if (serving) return; // dev and test servers serve the files from memory (below); they cannot emit files
      // Throws on an invalid or missing registry, which fails `vite build` (non-zero exit).
      for (const [fileName, source] of Object.entries(
        publicFiles(registryRoot, siteUrl(base), base),
      ))
        this.emitFile({ type: 'asset', fileName, source });
    },
    generateBundle(_options, bundle) {
      if (serving) return;
      const precache = [
        'index.html',
        'manifest.webmanifest',
        'catalog.json',
        'icons/icon.svg',
        'icons/icon-192.png',
        ...Object.keys(bundle).filter((f) => f.startsWith('assets/')),
      ].sort();
      this.emitFile({ type: 'asset', fileName: 'sw.js', source: serviceWorker(base, precache) });
    },
    configureServer(server) {
      // Dev: serve freshly generated files, so `vite` works on its own and always reflects the registry.
      // No service worker in dev (it is registered only in production builds).
      server.middlewares.use((req, res, next) => {
        const path = req.url?.split('?')[0] ?? '';
        const name = path.startsWith(server.config.base)
          ? path.slice(server.config.base.length)
          : '';
        const types: Record<string, string> = {
          'catalog.json': 'application/json; charset=utf-8',
          'llms.txt': 'text/plain; charset=utf-8',
          'resources.v1.json': 'application/json; charset=utf-8',
          'manifest.webmanifest': 'application/manifest+json; charset=utf-8',
        };
        if (!types[name]) return next();
        try {
          const body = publicFiles(registryRoot, siteUrl(server.config.base), server.config.base)[
            name
          ]!;
          res.setHeader('Content-Type', types[name]);
          res.setHeader('Cache-Control', 'no-store');
          res.end(body);
        } catch (e) {
          res.statusCode = 500;
          res.end(e instanceof Error ? e.message : String(e));
        }
      });
    },
  };
}

/** Where the registry lives relative to apps/web (the folder the site is built from). */
export const defaultRegistryRoot = (webDir: string): string => join(webDir, '../..');
